// Server-side view of the sector demos. src/sector-meta.json is generated by
// scripts/build-sectors.js from docs/secteurs/data/<slug>.js, so the labels,
// fictional company identities and e-mail vocabulary used in real e-mails
// can never drift from what the demo sites show. The slug arrives from a
// public form, so only known slugs resolve; anything else yields null.
const META = require("./sector-meta.json");

function getSector(slug) {
  return slug && Object.prototype.hasOwnProperty.call(META, slug) ? { slug, ...META[slug] } : null;
}

function sectorLabel(slug) {
  const s = getSector(slug);
  return s ? s.label : "";
}

module.exports = { getSector, sectorLabel };
